#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_STEPS 20
#define HASH_SIZE 1000003

// Directions: up, down, left, right
int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};

// State representation: 5 rows, each row has some columns
// We flatten into 13 positions (indices 0..12) but only 11 numbers + 2 zeros
// But careful: board is:
// row0: 1 cell (index 0)
// row1: 3 cells (indices 1,2,3)
// row2: 5 cells (indices 4,5,6,7,8)
// row3: 3 cells (indices 9,10,11)
// row4: 1 cell (index 12)
// Actually easier: treat as 5x5 but with invalid cells.
// We'll store as 5x5 array, with -1 for invalid cells.

int target[5][5] = {
    {1, -1, -1, -1, -1},
    {2, 3, 4, -1, -1},
    {5, 6, 7, 8, 9},
    {-1, -1, 10, 11, -1},
    {-1, -1, -1, -1, 0}
};

// For hashing: convert board to a string of 25 chars (with -1 as 'x')
void boardToString(int board[5][5], char *str) {
    int idx = 0;
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            if (board[i][j] == -1) str[idx++] = 'x';
            else str[idx++] = '0' + board[i][j];
        }
    }
    str[idx] = '\0';
}

int hashTable[HASH_SIZE];
char hashKeys[HASH_SIZE][26]; // 25 chars + null

int hashFunc(char *str) {
    unsigned long h = 5381;
    for (int i = 0; str[i]; i++) {
        h = ((h << 5) + h) + str[i];
    }
    return h % HASH_SIZE;
}

void insertHash(char *str, int dist) {
    int h = hashFunc(str);
    while (hashKeys[h][0] != '\0' && strcmp(hashKeys[h], str) != 0) {
        h = (h + 1) % HASH_SIZE;
    }
    if (hashKeys[h][0] == '\0') {
        strcpy(hashKeys[h], str);
        hashTable[h] = dist;
    }
}

int searchHash(char *str) {
    int h = hashFunc(str);
    while (hashKeys[h][0] != '\0') {
        if (strcmp(hashKeys[h], str) == 0) return hashTable[h];
        h = (h + 1) % HASH_SIZE;
    }
    return -1;
}

int isGoal(int board[5][5]) {
    for (int i = 0; i < 5; i++) {
        for (int j = 0; j < 5; j++) {
            if (board[i][j] != target[i][j]) return 0;
        }
    }
    return 1;
}

// BFS from initial state, limited to depth 20
int solve(int start[5][5]) {
    // Queue for BFS
    int boards[100000][5][5];
    int dist[100000];
    int front = 0, rear = 0;

    // Initialize hash for visited
    for (int i = 0; i < HASH_SIZE; i++) hashKeys[i][0] = '\0';

    // Copy start to queue
    for (int i = 0; i < 5; i++)
        for (int j = 0; j < 5; j++)
            boards[rear][i][j] = start[i][j];
    dist[rear] = 0;
    char str[26];
    boardToString(start, str);
    insertHash(str, 0);
    rear++;

    while (front < rear) {
        int cur[5][5];
        for (int i = 0; i < 5; i++)
            for (int j = 0; j < 5; j++)
                cur[i][j] = boards[front][i][j];
        int d = dist[front];
        front++;

        if (d > MAX_STEPS) continue;

        if (isGoal(cur)) {
            return d;
        }

        // Find empty positions (0)
        for (int i = 0; i < 5; i++) {
            for (int j = 0; j < 5; j++) {
                if (cur[i][j] == 0) {
                    // For each direction
                    for (int k = 0; k < 4; k++) {
                        int ni = i + dr[k];
                        int nj = j + dc[k];
                        if (ni >= 0 && ni < 5 && nj >= 0 && nj < 5 && cur[ni][nj] != -1) {
                            // swap
                            int next[5][5];
                            for (int ii = 0; ii < 5; ii++)
                                for (int jj = 0; jj < 5; jj++)
                                    next[ii][jj] = cur[ii][jj];
                            next[i][j] = next[ni][nj];
                            next[ni][nj] = 0;

                            boardToString(next, str);
                            int found = searchHash(str);
                            if (found == -1) {
                                insertHash(str, d+1);
                                for (int ii = 0; ii < 5; ii++)
                                    for (int jj = 0; jj < 5; jj++)
                                        boards[rear][ii][jj] = next[ii][jj];
                                dist[rear] = d+1;
                                rear++;
                            }
                        }
                    }
                }
            }
        }
    }

    return -1; // Not found within 20
}

